import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第六十一卦 中孚 風澤中孚 巽上兌下","description":"周易 - 第六十一卦 中孚 風澤中孚 巽上兌下","frontmatter":{"title":"第六十一卦 中孚 風澤中孚 巽上兌下","description":"周易 - 第六十一卦 中孚 風澤中孚 巽上兌下"},"headers":[],"relativePath":"classics/zhouyi/062.md","filePath":"classics/zhouyi/062.md"}'),l={name:"classics/zhouyi/062.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="中孚" tabindex="-1">中孚 <a class="header-anchor" href="#中孚" aria-label="Permalink to “中孚”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>豚魚吉，利涉大川，利貞。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>中孚，柔在內而剛得中。說而巽，孚，乃化邦也。豚魚吉，信及豚魚也。利涉大川，乘木舟虛也。中孚以利貞，乃應乎天也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤上有風，中孚；君子以議獄緩死。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>虞吉，有他不燕。象曰：初九虞吉， 志未變也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。象曰：其子和之，中心願也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>得敵，或鼓或罷，或泣或歌。象曰：可鼓或罷，位不當也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>月幾望，馬匹亡，無咎。象曰：馬匹亡，絕類上也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>有孚攣如，無咎。象曰：有孚攣如，位正當也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>翰音登於天，貞兇。象曰：翰音登於天，何可長也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
